tool_input_args.value:
node -e "
const fs = require('fs');

// --- 1. Add calendar event to alice.ics ---
const calFile = '/workspace/testbed/calendar/alice.ics';
let cal = fs.readFileSync(calFile, 'utf8');

const newEvent = \`BEGIN:VEVENT
SUMMARY:Final Onboarding Review Meeting
DTSTART:20260910T140000
DTEND:20260910T150000
DTSTAMP:\${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'').slice(0,15)}Z
DESCRIPTION:
LOCATION:
END:VEVENT\`;

// Insert new event before END:VCALENDAR
cal = cal.replace('END:VCALENDAR', newEvent + '\nEND:VCALENDAR');
fs.writeFileSync(calFile, cal);
console.log('Calendar event created successfully.');

// --- 2. Send email to Priya ---
const subject = 'Final Onboarding Review Meeting - September 10, 2026';
const content = \`Hi Priya,

I wanted to inform you that a Final Onboarding Review Meeting has been scheduled for September 10, 2026, at 2:00 PM.

Please let me know if you have any questions or conflicts with this time.

Best regards,
Alice\`;

const email = \`From: alice@example.com
To: priya@example.com
Subject: \${subject}
MIME-Version: 1.0
Content-Type: text/plain; charset=\"utf-8\"

\${content}
\`;

// Save to both sender and recipient folders
const senderDir = '/workspace/testbed/emails/alice';
const recipientDir = '/workspace/testbed/emails/priya';
fs.mkdirSync(recipientDir, { recursive: true });

fs.writeFileSync(senderDir + '/' + subject + '.eml', email);
fs.writeFileSync(recipientDir + '/' + subject + '.eml', email);
console.log('Email sent to Priya successfully.');
"
